args.new:
def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = cols
        elif end == 0:
            # rfind returning 0 would produce an empty line and identical
            # remaining text (text[:0]=='' and text[0:]==text), causing an
            # infinite loop for inputs with a leading space. Advancing by one
            # preserves concatenation and avoids empty lines.
            end = 1
        line, text = text[:end], text[end:]
        lines.append(line)
    if text:
        lines.append(text)
    return lines
